import { useState } from 'react'
import { useHostState } from './hostState'

interface Note { id: string; text: string }

export default function App() {
  const [notes, setNotes] = useHostState<Note[]>('notes', [])
  const [input, setInput] = useState('')

  const addNote = () => {
    if (input.trim()) {
      setNotes([...notes, { id: Date.now().toString(), text: input.trim() }])
      setInput('')
    }
  }

  return (
    <div className="min-h-screen p-8">
      <h1>Notes</h1>
      <input value={input} onChange={e => setInput(e.target.value)} />
      <button onClick={addNote}>Add</button>
      <ul>{notes.map(n => <li key={n.id}>{n.text}</li>)}</ul>
    </div>
  )
}
